use std::cmp::Ordering;

#[derive(Clone, Debug)]
struct Big { d: Vec<u32> }

impl Big {
    fn from_u64(mut v: u64) -> Big {
        let mut d = Vec::with_capacity(6);
        while v != 0 { d.push((v & 0xffff_ffff) as u32); v >>= 32; }
        Big { d }
    }
    fn is_zero(&self) -> bool { self.d.is_empty() }
    fn trim(&mut self) { while let Some(&0) = self.d.last() { self.d.pop(); } }
    fn cmp_big(&self, other: &Big) -> Ordering {
        if self.d.len() != other.d.len() { return self.d.len().cmp(&other.d.len()); }
        for i in (0..self.d.len()).rev() {
            if self.d[i] != other.d[i] { return self.d[i].cmp(&other.d[i]); }
        }
        Ordering::Equal
    }
    fn mul_u32(&mut self, m: u32) {
        if m == 0 { self.d.clear(); return; }
        let mut carry: u64 = 0;
        for limb in self.d.iter_mut() {
            let t = (*limb as u64) * (m as u64) + carry;
            *limb = (t & 0xffff_ffff) as u32;
            carry = t >> 32;
        }
        while carry != 0 { self.d.push((carry & 0xffff_ffff) as u32); carry >>= 32; }
    }
    fn mul_pow10(&mut self, mut e: u32) {
        if self.is_zero() { return; }
        while e >= 9 { self.mul_u32(1_000_000_000); e -= 9; }
        if e > 0 {
            const P: [u32; 9] = [1,10,100,1000,10_000,100_000,1_000_000,10_000_000,100_000_000];
            self.mul_u32(P[e as usize]);
        }
    }
    fn shl_bits(&mut self, n: usize) {
        if self.is_zero() || n == 0 { return; }
        let limbs = n / 32;
        let bits = n % 32;
        if bits > 0 {
            let mut carry: u32 = 0;
            for limb in self.d.iter_mut() {
                let nv = (*limb << bits) | carry;
                carry = *limb >> (32 - bits);
                *limb = nv;
            }
            if carry != 0 { self.d.push(carry); }
        }
        if limbs > 0 {
            let mut nd = vec![0u32; limbs];
            nd.extend_from_slice(&self.d);
            self.d = nd;
        }
    }
    fn shl(&self, n: usize) -> Big { let mut c = self.clone(); c.shl_bits(n); c }
    fn sub_assign(&mut self, other: &Big) {
        let mut borrow: i64 = 0;
        for i in 0..self.d.len() {
            let o = if i < other.d.len() { other.d[i] as i64 } else { 0 };
            let mut t = self.d[i] as i64 - o - borrow;
            if t < 0 { t += 1i64 << 32; borrow = 1; } else { borrow = 0; }
            self.d[i] = t as u32;
        }
        debug_assert_eq!(borrow, 0);
        self.trim();
    }
    fn pow2(e: usize) -> Big { Big::from_u64(1).shl(e) }
}

